/* Files generated by the server (Excel exports): Cloud Run keeps nothing, the page saves the body it receives. */
import { unwrap } from "./client";

/** The file name of a Content-Disposition header (attachment; filename="x.xlsx"), else the fallback. */
export function attachmentName(disposition: string | null, fallback: string): string {
  const m = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/.exec(disposition ?? "");
  const name = m?.[1]?.replace(/['"]/g, "").trim();
  return name || fallback;
}

/** Hands the file to the browser, which saves it in the downloads. */
export function saveFile(blob: Blob, name: string): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

/**
 * Saves the file answered by an export call (client.GET/POST with parseAs: "blob") and returns its name;
 * throws an ApiError like unwrap() when the server refuses.
 */
export async function saveExport(call: Promise<{ data?: Blob; error?: unknown; response: Response }>, fallback: string): Promise<string> {
  const blob = await unwrap(call);
  const name = attachmentName((await call).response.headers.get("content-disposition"), fallback);
  saveFile(blob, name);
  return name;
}
